#!/usr/bin/env node
"use strict";
// smoke:fsrs — Retention P1 golden gate (RETENTION_PROGRAM_RECON_2026_07_02.md §4.1/§7).
// Asserts public/js/fsrs-core.js against the COMMITTED reference vectors generated by the
// pinned ts-fsrs@<fixture.provenance.reference_version> (FSRS-6.0, long-term regime, no fuzz)
// — see scripts/premium/fixtures/fsrs/ (the gate itself never calls ts-fsrs). Then the
// PRODUCT contracts the adversarial critique demanded: Again→due-now (same-session retest,
// M8), Δt<0 clamp (clock skew never throws, M10), skip folds exactly like its grade via the
// ONE shared applyRow (M9), seed branches incl. interval=0 (M7), replay watermark (B4),
// determinism, D∈[1,10].
// Run: node scripts/premium/fsrs-core-smoke.js   (or npm run smoke:fsrs)

const path = require("path");
const F = require(path.join(__dirname, "..", "..", "public", "js", "fsrs-core.js"));
const FIX = require(path.join(__dirname, "fixtures", "fsrs", "fsrs6-golden-v1.json"));

let pass = 0; const failures = [];
const eq = (cond, msg) => { if (cond) pass++; else failures.push(msg); };
const close = (a, b) => Math.abs(a - b) < 1e-7;

// ── 1) golden parity: every scenario step must reproduce S/D/interval/reps/lapses ──────────
eq(FIX.provenance && FIX.provenance.generation === "FSRS-6.0" && FIX.provenance.reference === "ts-fsrs",
  "fixture provenance missing/unpinned");
eq(String(F.REFERENCE) === "ts-fsrs@" + FIX.provenance.reference_version,
  `engine REFERENCE ${F.REFERENCE} != fixture ts-fsrs@${FIX.provenance.reference_version} — regenerate or re-pin`);
eq(JSON.stringify(F.DEFAULT_W) === JSON.stringify(FIX.provenance.weights), "weights differ from fixture provenance");
eq(F.REQUEST_RETENTION === FIX.provenance.request_retention, "request_retention differs");

const T0 = Date.UTC(2026, 0, 1);
for (const sc of FIX.scenarios) {
  let state = null, nowMs = T0, ok = true, detail = "";
  for (let i = 0; i < sc.steps.length; i++) {
    const st = sc.steps[i];
    nowMs += st.dt * 86400000;
    state = F.nextState(state, st.grade, nowMs);
    if (!(close(state.stability, st.stability) && close(state.difficulty, st.difficulty) &&
          state.refIntervalDays === st.scheduled_days && state.reps === st.reps && state.lapses === st.lapses)) {
      ok = false;
      detail = `step ${i} (dt=${st.dt},g=${st.grade}): got S=${state.stability} D=${state.difficulty} ivl=${state.refIntervalDays} reps=${state.reps} lapses=${state.lapses}; want S=${st.stability} D=${st.difficulty} ivl=${st.scheduled_days} reps=${st.reps} lapses=${st.lapses}`;
      break;
    }
  }
  eq(ok, `golden scenario '${sc.name}' diverged — ${detail}`);
}

// ── 2) product contracts ────────────────────────────────────────────────────────────────────
{ // Again → due NOW (same-session retest preserved); intervalDays projection = 0
  let s = F.initState(3, T0);
  const after = F.nextState(s, 1, T0 + 3 * 86400000);
  eq(after.dueMs === T0 + 3 * 86400000 && after.intervalDays === 0 && after.refIntervalDays >= 1,
    "Again contract broken: due must be NOW (projection 0) while refInterval stays reference");
  const good = F.nextState(s, 3, T0 + 3 * 86400000);
  eq(good.dueMs === T0 + 3 * 86400000 + good.refIntervalDays * 86400000 && good.intervalDays === good.refIntervalDays,
    "Good due/interval projection wrong");
}
{ // Δt < 0 (clock skew) never throws, clamps to same-day
  const s = F.initState(3, T0 + 10 * 86400000);
  let threw = false, out = null;
  try { out = F.nextState(s, 3, T0); } catch (_) { threw = true; }
  eq(!threw && out && isFinite(out.stability) && out.stability > 0, "negative Δt threw or produced junk");
  const sameDay = F.nextState(s, 3, T0 + 10 * 86400000);
  eq(close(out.stability, sameDay.stability), "negative Δt not clamped to the t=0 branch");
}
{ // skip folds EXACTLY like its grade through the one shared step (M9)
  const s = F.initState(3, T0);
  const viaSkip = F.applyRow(s, { kind: "skip", grade: 1, reviewed_at: new Date(T0 + 2 * 86400000).toISOString() });
  const viaNext = F.nextState(s, 1, T0 + 2 * 86400000);
  eq(JSON.stringify(viaSkip) === JSON.stringify(viaNext), "skip row diverged from nextState(Again)");
}
{ // seed branches (M7): interval>0 → S=interval, D=D0(Good); interval=0 → initState(Again) floors; due untouched
  const a = F.seedFromSm2({ interval: 5, reps: 3, lapses: 1 }, T0);
  eq(close(a.stability, 5) && a.reps === 3 && a.lapses === 1 && a.dueMs === null, "seed interval>0 branch wrong");
  const b = F.seedFromSm2({ interval: 0, reps: 0, lapses: 2 }, T0);
  const againInit = F.initState(1, T0);
  eq(close(b.stability, againInit.stability) && close(b.difficulty, againInit.difficulty) && b.lapses === 2 && b.dueMs === null,
    "seed interval=0 branch must equal initState(Again) floors");
  eq(b.stability >= F.S_MIN, "seed produced S below S_MIN");
}
{ // replay watermark (B4): rows before the last seed are ignored for state
  const iso = (d) => new Date(T0 + d * 86400000).toISOString();
  const r1 = { kind: "review", grade: 3, reviewed_at: iso(0) };
  const r2 = { kind: "seed", reviewed_at: iso(1), meta_json: JSON.stringify({ interval: 5, reps: 4, lapses: 1, scheme: "sm2-lite" }) };
  const r3 = { kind: "review", grade: 3, reviewed_at: iso(2) };
  const withPre = F.replay([r1, r2, r3]);
  const withoutPre = F.replay([r2, r3]);
  eq(JSON.stringify(withPre) === JSON.stringify(withoutPre) && withPre.reps === 5,
    "replay watermark broken: pre-seed rows leaked into state");
  const liveFold = F.applyRow(F.applyRow(null, r2), r3);
  eq(JSON.stringify(withPre) === JSON.stringify(liveFold), "replay != incremental applyRow fold (oracle broken)");
}
{ // determinism + D bounds + S monotone shrink on Again
  const run = () => { let s = null, now = T0; for (const g of [3, 3, 1, 3, 2, 4, 1, 3]) { now += 86400000 * 2; s = F.nextState(s, g, now); } return s; };
  const x = run(), y = run();
  eq(JSON.stringify(x) === JSON.stringify(y), "engine not deterministic");
  let s = F.initState(3, T0);
  s = F.nextState(s, 3, T0 + 3 * 86400000);
  const preS = s.stability;
  const failed = F.nextState(s, 1, T0 + 20 * 86400000);
  eq(failed.stability <= preS, "Again increased stability");
  eq(x.difficulty >= 1 && x.difficulty <= 10, "difficulty out of [1,10]");
}
{ // retrievability sanity: R(0)=1-ish, decreasing in t; R at S ≈ 0.9
  const s = F.initState(3, T0);
  const r0 = F.retrievability(s, T0);
  const rS = F.retrievability(s, T0 + Math.round(s.stability) * 86400000);
  const rLong = F.retrievability(s, T0 + 300 * 86400000);
  eq(r0 === 1 && rS < r0 && rLong < rS && rLong > 0, "retrievability not monotone-decreasing from 1");
}

const total = pass + failures.length;
if (failures.length) {
  console.error(`smoke:fsrs FAIL (${pass}/${total})`);
  for (const f of failures) console.error("  ✗ " + f);
  process.exitCode = 1;
} else {
  console.log(`smoke:fsrs OK (${pass}/${total}) — golden parity ${FIX.scenarios.length} scenarios/${FIX.scenarios.reduce((n, s) => n + s.steps.length, 0)} steps vs ${FIX.provenance.reference}@${FIX.provenance.reference_version} (${FIX.provenance.generation}) + product contracts (Again→due-now, Δt clamp, skip-fold, seed, replay-watermark, determinism)`);
}
